SELECT COUNT(DISTINCT a.lawmail) FROM attorney a WHERE a.lawmail IN (
    SELECT DISTINCT ca.counselmail FROM case_attorney ca JOIN cases c ON ca.docketkey = c.filekey WHERE c.visacls::text = 'H-1B'
);

SELECT a.lawmail, a.attorney_profile->'name'->>'first', a.attorney_profile->'name'->>'last' FROM attorney a WHERE a.lawmail IN (
    SELECT ca.counselmail FROM case_attorney ca JOIN cases c ON ca.docketkey = c.filekey WHERE c.visacls::text = 'H-1B'
) AND a.lawmail NOT IN (
    SELECT DISTINCT ca.counselmail FROM case_attorney ca JOIN cases c ON ca.docketkey = c.filekey WHERE c.visacls::text = 'H-1B' AND ca.counselmail IN (SELECT lawmail FROM attorney)
);
